    dict(key='29-class-2', kind='code', title='PostQuantumDemo — encapsulate, then decapsulate',
         body='// PostQuantumDemo: the demo: ML-KEM through javax.crypto.KEM\nKEM kem = KEM.getInstance("ML-KEM");\nKEM.Encapsulated first = kem.newEncapsulator(pair.getPublic()).encapsulate();\nbyte[] opened = kem.newDecapsulator(pair.getPrivate())\n        .decapsulate(first.encapsulation()).getEncoded();',
         narration='The sender encapsulates to the public key, and gets a ciphertext and a key. [[slnc 300]] The bank decapsulates the ciphertext with its private key, and gets the same key.'),
